style.css:
html, body {
  overflow-x: auto; 
  overflow-y: auto;   
  margin: 0; 
  padding: 0; 
}

html::before,
html::after,
body::before,
body::after,
main::before,
main::after,
nav::before,
nav::after {
  content: '';
  position: fixed;
  background-image: url("https://i.redd.it/n3aaowanynj61.gif");
  background-size: contain;
  background-repeat: no-repeat;
  z-index: 9999; 
  pointer-events: none;
}

html::before {
  top: calc(20% - 125px); 
  left: 100%;
  width: 150px; 
  height: 150px;
  animation: furret-walk 15s linear infinite 0s; 
}

html::after {
  top: calc(40% - 125px); 
  left: 100%;
  width: 180px; 
  height: 180px;
  animation: furret-walk 12s linear infinite 3s;
}

body::before {
  top: calc(60% - 125px); 
  left: 100%;
  width: 140px; 
  height: 140px;
  animation: furret-walk 20s linear infinite 1s; 
}

body::after {
  top: calc(95% - 125px); 
  left: 100%;
  width: 170px; 
  height: 170px;
  animation: furret-walk 18s linear infinite 5s; 
}

main::before {
  top: calc(80% - 125px); 
  left: 100%;
  width: 200px; 
  height: 200px;
  animation: furret-walk 25s linear infinite 2s; 
}

main::after {
  top: calc(30% - 125px); 
  left: 100%;
  width: 160px;
  height: 160px;
  animation: furret-walk 22s linear infinite 4s; 
}

nav::before {
  top: calc(50% - 125px); 
  left: 100%;
  width: 160px; 
  height: 160px;
  animation: furret-walk 20s linear infinite 1s; 
}

nav::after {
  top: calc(70% - 125px); 
  left: 100%;
  width: 180px;
  height: 180px;
  animation: furret-walk 18s linear infinite 6s;
}

@keyframes furret-walk {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-120vw); 
  }
}
